preConditionHook:
// THE SMALL-PULLBACK TREND, the strongest kind of trend there is. Since the
// current trend leg began, the DEEPEST pullback so far has stayed below a
// threshold. Three sources are three statements of one measurement: T23-06 is
// the state primitive (track the largest pullback since the trend began),
// T23-07 the test against a fraction of the average daily range, and V00-40
// the same test with Brooks's raw Emini number (pullbacks under 3 to 4 points
// on a 12-point average range, which IS about a quarter of the range, so the
// two forms agree). A state primitive with no comparison is not a rule and
// the comparison is meaningless without the state, so they are one rule.
//
// TWO THRESHOLD FORMS, one switch. usePointsThreshold = 0 (the default) is
// the portable form, smallPullbackFraction of the recent average daily range;
// set it above 0 and the threshold is maxPullbackPoints in PRICE POINTS, kept
// so the book's own example reproduces exactly. maxPullbackPoints is
// instrument-specific and must be set per symbol in the grid, as
// BreakoutRunsWithoutPullback's scalpDistance is. The merged default of 3
// points is preserved but inert until the switch is turned on.
//
// THE LEG RESET IS THE ALWAYS-IN FLIP, the standing corpus decision, inlined
// here as TrendDurationBars inlines it and with the same inputs so every
// consumer reads the same state: the direction FLIPS on consecutiveBars
// consecutive STRONG TREND BARS -- body at least bodyFraction of the bar's
// own range and BOTH tails no more than tailFraction of it -- holds until the
// opposite flip, and is UNDEFINED (aiDir = 0) until the first flip ever.
// T23-07's session scoping is NOT baked in: reset-on-leg-start is the general
// form and a session reset is only one choice of leg.
//
// THE TRACKER, straight from the merged pseudocode: extend the running
// extreme first, and measure the give-back only on bars that did NOT extend
// it, so a new-high bar's own low is never counted as a pullback. The
// trackers are seeded on the flip bar and that bar is skipped, since its own
// range is the start of the leg rather than a retracement of it.
//
// Not ProfitProtector, which tracks give-back from peak PROFIT on an open
// position: this tracks give-back from peak PRICE with no position involved.
// Kept apart from PullbackDepthExceedsPriorMax, which compares the LIVE
// pullback with that historical maximum and fires on different bars.
//
// AverageDailyRange is INLINED, same text as its own file, per the composites
// decision; its dayLookback guard WRAPS the date read rather than being ANDed
// with it, because EasyLanguage does not short-circuit. Compared, never
// divided.
//
// Mirrored: the long side is the bull leg's give-back below its running high,
// the short side the bear leg's give-back above its running low.
//
// Deepest bar touched: max(maxScanBars + 1, consecutiveBars - 1).
allBull = true;
allBear = true;
for (kk = 0; kk < (int)consecutiveBars; ++kk) {
    rng = high[kk] - low[kk];
    if (el_le(close[kk], open[kk])) allBull = false;
    if (el_lt(close[kk] - open[kk], bodyFraction * rng)) allBull = false;
    if (el_gt(high[kk] - close[kk], tailFraction * rng)) allBull = false;
    if (el_gt(open[kk] - low[kk], tailFraction * rng)) allBull = false;
    if (el_ge(close[kk], open[kk])) allBear = false;
    if (el_lt(open[kk] - close[kk], bodyFraction * rng)) allBear = false;
    if (el_gt(close[kk] - low[kk], tailFraction * rng)) allBear = false;
    if (el_gt(high[kk] - open[kk], tailFraction * rng)) allBear = false;
}
flipped = false;
if (allBull && aiDir != 1) {
    aiDir = 1;
    flipped = true;
}
if (allBear && aiDir != -1 && flipped == false) {
    aiDir = -1;
    flipped = true;
}
if (flipped) {
    runHigh = high[0];
    runLow = low[0];
    pbMaxUp = 0.0;
    pbMaxDn = 0.0;
}
if (flipped == false) {
    if (el_gt(high[0], runHigh)) runHigh = high[0];
    if (el_lt(low[0], runLow)) runLow = low[0];
    if (el_lt(high[0], runHigh)) {
        if (el_gt(runHigh - low[0], pbMaxUp)) pbMaxUp = runHigh - low[0];
    }
    if (el_gt(low[0], runLow)) {
        if (el_gt(high[0] - runLow, pbMaxDn)) pbMaxDn = high[0] - runLow;
    }
}
adrSum = 0.0;
adrDays = 0;
dHi = 0.0;
dLo = 0.0;
dOpen = false;
for (kk = 1; kk <= (int)maxScanBars; ++kk) {
    if (el_lt((double)adrDays, dayLookback)) {
        if (day_of(ctx.Time(kk)) != day_of(ctx.Time(0))) {
            if (!dOpen) {
                dHi = high[kk];
                dLo = low[kk];
                dOpen = true;
            } else {
                if (el_gt(high[kk], dHi)) dHi = high[kk];
                if (el_lt(low[kk], dLo)) dLo = low[kk];
            }
            if (day_of(ctx.Time(kk + 1)) != day_of(ctx.Time(kk))) {
                adrSum = adrSum + (dHi - dLo);
                adrDays = adrDays + 1;
                dOpen = false;
            }
        }
    }
}
adrReady = el_ge((double)adrDays, dayLookback);
if (adrReady) {
    adr = adrSum / dayLookback;
} else {
    adr = 0.0;
}
pbLimit = smallPullbackFraction * adr;
limitReady = adrReady;
if (el_gt(usePointsThreshold, 0.0)) {
    pbLimit = maxPullbackPoints;
    limitReady = true;
}
smallUp = (aiDir == 1) && limitReady && el_le(pbMaxUp, pbLimit);
smallDn = (aiDir == -1) && limitReady && el_le(pbMaxDn, pbLimit);
